using System.Globalization;
using System.Text;

namespace SciToolbox.Core;

// MARK: - AppLanguage（界面语言管理器）

/// <summary>界面语言管理器（对应 macOS 版 AppLanguage）。语言偏好持久化，跨会话记忆。</summary>
public sealed class AppLanguage
{
    public static AppLanguage Shared { get; } = new();

    public enum Language { Zh, En }

    private const string PrefsKey = "appLanguage";

    public event Action? Changed;

    public Language Current
    {
        get => Prefs.GetString(PrefsKey, "zh") == "en" ? Language.En : Language.Zh;
        set
        {
            if (value == Current) return;
            Prefs.SetString(PrefsKey, value == Language.En ? "en" : "zh");
            Changed?.Invoke();
        }
    }

    public static Language Cur => Shared.Current;

    public static CultureInfo CurrentCulture =>
        Cur == Language.En ? CultureInfo.GetCultureInfo("en-US") : CultureInfo.GetCultureInfo("zh-CN");
}

