    public static string T(Key k) => Table.TryGetValue(k, out var pair)
        ? (AppLanguage.Cur == AppLanguage.Language.Zh ? pair.zh : pair.en)
        : k.ToString();

    public static string T(Key k, params object[] args) => Format(T(k), args);

    /// 顺序替换 %@（字符串）/ %d（整数）占位符，兼容 macOS 版 printf 风格文案。
    public static string Format(string fmt, params object[] args)
    {
        if (string.IsNullOrEmpty(fmt) || args.Length == 0) return fmt;
        var sb = new StringBuilder();
        int ai = 0;
        for (int i = 0; i < fmt.Length; i++)
        {
            if (fmt[i] == '%' && i + 1 < fmt.Length)
            {
                char next = fmt[i + 1];
                if (next == '@' || next == 'd' || next == 'f' || next == 's')
                {
                    if (ai < args.Length)
                    {
                        var a = args[ai++];
                        sb.Append(next == 'd' ? Convert.ToInt64(a).ToString(CultureInfo.InvariantCulture)
                                              : a?.ToString() ?? "");
                    }
                    i++;
                    continue;
                }
                if (next == '%')
                {
                    sb.Append('%');
                    i++;
                    continue;
                }
            }
            sb.Append(fmt[i]);
        }
        return sb.ToString();
    }

